c7-5.solution:
#include <stdio.h>

int sum_to(int n) {
    if (n == 0) { return 0; }
    return n + sum_to(n - 1);
}

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) { return 1; }
    printf("%d\n", sum_to(n));
    return 0;
}

