c7-7.solution:
#include <stdio.h>

int digit_sum(int n) {
    int sum = 0;
    while (n > 0) { sum += n % 10; n /= 10; }
    return sum;
}

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) { return 1; }
    printf("%d\n", digit_sum(n));
    return 0;
}
